// artHash64 mints a syntactically-valid 64-hex selection/sha for tests.
func artHash64(c byte) string { return strings.Repeat(string(c), 64) }

// TestArtOverrideMethods covers the art_overrides method set (artwork): the
// (entity_id, entity_kind) round-trip, the upsert overwrite (ONE row per
// entity, sibling rows untouched), delete idempotence, and the unknown-id
// miss (wrapped sql.ErrNoRows).
func TestArtOverrideMethods(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	t.Run("round_trip", func(t *testing.T) {
		// The two id spaces share the one table, exactly like title_overrides:
		// a ser_ series id and an item id are distinct rows.
		cases := []struct {
			name       string
			entityID   string
			entityKind string
			selection  string
		}{
			{"series", "ser_7_beef", "series", "art_" + artHash64('a')},
			{"item", "itm_01HZZ", "item", "art_" + artHash64('b')},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				stamp, err := s.UpsertArtOverride(ctx, tc.entityID, tc.entityKind, tc.selection)
				if err != nil {
					t.Fatalf("UpsertArtOverride: %v", err)
				}
				if stamp == "" {
					t.Fatal("UpsertArtOverride stamp = empty, want RFC3339Nano TEXT")
				}
				got, err := s.GetArtOverride(ctx, tc.entityID, tc.entityKind)
				if err != nil {
					t.Fatalf("GetArtOverride: %v", err)
				}
				if got != tc.selection {
					t.Fatalf("GetArtOverride(%s/%s) = %q, want %q", tc.entityID, tc.entityKind, got, tc.selection)
				}
			})
		}
	})

	// upsert_overwrite: the composite PK means a second upsert overwrites the
	// selection in place — one row per (entity, kind), the sibling entity's
	// row and the sibling kind's row untouched.
	t.Run("upsert_overwrite", func(t *testing.T) {
		if _, err := s.UpsertArtOverride(ctx, "ser_ow", "series", "art_"+artHash64('1')); err != nil {
			t.Fatalf("UpsertArtOverride #1: %v", err)
		}
		if _, err := s.UpsertArtOverride(ctx, "ser_ow", "series", "art_"+artHash64('2')); err != nil {
			t.Fatalf("UpsertArtOverride #2: %v", err)
		}
		got, err := s.GetArtOverride(ctx, "ser_ow", "series")
		if err != nil {
			t.Fatalf("GetArtOverride after overwrite: %v", err)
		}
		if got != "art_"+artHash64('2') {
			t.Fatalf("selection = %q, want the latest write %q", got, "art_"+artHash64('2'))
		}
		var n int
		if err := s.db.QueryRowContext(ctx,
			"SELECT COUNT(*) FROM art_overrides WHERE entity_id = 'ser_ow'").Scan(&n); err != nil {
			t.Fatalf("count rows: %v", err)
		}
		if n != 1 {
			t.Fatalf("rows for ser_ow = %d, want 1 (upsert, never duplicate)", n)
		}
		// A different entity_kind on the SAME entity id is a distinct row.
		if _, err := s.UpsertArtOverride(ctx, "ser_ow", "library", "art_"+artHash64('3')); err != nil {
			t.Fatalf("UpsertArtOverride other kind: %v", err)
		}
		if got, err := s.GetArtOverride(ctx, "ser_ow", "library"); err != nil || got != "art_"+artHash64('3') {
			t.Fatalf("GetArtOverride(ser_ow/library) = %q, %v; want untouched other-kind row", got, err)
		}
	})

	t.Run("delete_idempotent", func(t *testing.T) {
		if _, err := s.UpsertArtOverride(ctx, "itm_del", "item", "art_"+artHash64('4')); err != nil {
			t.Fatalf("UpsertArtOverride: %v", err)
		}
		if err := s.DeleteArtOverride(ctx, "itm_del", "item"); err != nil {
			t.Fatalf("DeleteArtOverride: %v", err)
		}
		if err := s.DeleteArtOverride(ctx, "itm_del", "item"); err != nil {
			t.Fatalf("DeleteArtOverride repeat (must be a no-op): %v", err)
		}
		if _, err := s.GetArtOverride(ctx, "itm_del", "item"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetArtOverride after delete = %v, want sql.ErrNoRows", err)
		}
	})

	t.Run("unknown_id_miss", func(t *testing.T) {
		if _, err := s.GetArtOverride(ctx, "ser_absent", "series"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetArtOverride missing = %v, want sql.ErrNoRows", err)
		}
	})
}

// TestArtFetchMethods covers the art_fetches method set (artwork): the
// url_hash round-trip (sha256 + kind), the upsert overwrite of a drifted
// upstream, delete idempotence, the unknown-hash miss, and ListArtFetchRefs
// as the DISTINCT, sha-ordered GC reference set.
func TestArtFetchMethods(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	t.Run("round_trip", func(t *testing.T) {
		// kind rides along opaque: an empty kind is stored verbatim (the
		// DEFAULT 'poster' applies to inserts that omit the column, and the
		// method always supplies one explicitly — the caller owns the default).
		cases := []struct {
			name    string
			urlHash string
			sha     string
			kind    string
		}{
			{"poster", artHash64('p'), artHash64('a'), "poster"},
			{"background", artHash64('q'), artHash64('b'), "background"},
			{"empty_kind", artHash64('r'), artHash64('c'), ""},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				if err := s.InsertArtFetch(ctx, tc.urlHash, tc.sha, tc.kind); err != nil {
					t.Fatalf("InsertArtFetch: %v", err)
				}
				got, err := s.LookupArtFetch(ctx, tc.urlHash)
				if err != nil {
					t.Fatalf("LookupArtFetch: %v", err)
				}
				if got != tc.sha {
					t.Fatalf("LookupArtFetch(%s) = %q, want %q", tc.urlHash, got, tc.sha)
				}
				var kind string
				if err := s.db.QueryRowContext(ctx,
					"SELECT kind FROM art_fetches WHERE url_hash = ?", tc.urlHash).Scan(&kind); err != nil {
					t.Fatalf("read kind: %v", err)
				}
				if kind != tc.kind {
					t.Fatalf("kind = %q, want %q (stored verbatim)", kind, tc.kind)
				}
			})
		}
	})

	// upsert_overwrite: the same url_hash re-pointed at new bytes after
	// upstream content drift — one row, new sha.
	t.Run("upsert_overwrite", func(t *testing.T) {
		h := artHash64('o')
		if err := s.InsertArtFetch(ctx, h, artHash64('1'), "poster"); err != nil {
			t.Fatalf("InsertArtFetch #1: %v", err)
		}
		if err := s.InsertArtFetch(ctx, h, artHash64('2'), "poster"); err != nil {
			t.Fatalf("InsertArtFetch #2: %v", err)
		}
		got, err := s.LookupArtFetch(ctx, h)
		if err != nil {
			t.Fatalf("LookupArtFetch after overwrite: %v", err)
		}
		if got != artHash64('2') {
			t.Fatalf("sha = %q, want the drifted %q", got, artHash64('2'))
		}
		var n int
		if err := s.db.QueryRowContext(ctx,
			"SELECT COUNT(*) FROM art_fetches WHERE url_hash = ?", h).Scan(&n); err != nil {
			t.Fatalf("count rows: %v", err)
		}
		if n != 1 {
			t.Fatalf("rows for %s = %d, want 1 (upsert, never duplicate)", h, n)
		}
	})

	t.Run("delete_idempotent", func(t *testing.T) {
		h := artHash64('d')
		if err := s.InsertArtFetch(ctx, h, artHash64('e'), "poster"); err != nil {
			t.Fatalf("InsertArtFetch: %v", err)
		}
		if err := s.DeleteArtFetch(ctx, h); err != nil {
			t.Fatalf("DeleteArtFetch: %v", err)
		}
		if err := s.DeleteArtFetch(ctx, h); err != nil {
			t.Fatalf("DeleteArtFetch repeat (must be a no-op): %v", err)
		}
		if _, err := s.LookupArtFetch(ctx, h); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("LookupArtFetch after delete = %v, want sql.ErrNoRows", err)
		}
	})

	t.Run("unknown_hash_miss", func(t *testing.T) {
		if _, err := s.LookupArtFetch(ctx, artHash64('8')); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("LookupArtFetch missing = %v, want sql.ErrNoRows", err)
		}
	})

	// list_refs: DISTINCT shas in sha order regardless of how many url
	// hashes point at each — the GC union's reference half; a deleted fetch
	// row's sha drops out.
	t.Run("list_refs_distinct_and_ordered", func(t *testing.T) {
		refsStore := openStore(t)
		seeds := []struct{ hash, sha string }{
			{artHash64('h'), artHash64('9')},
			{artHash64('i'), artHash64('0')},
			{artHash64('j'), artHash64('9')}, // second url, same blob
		}
		for _, seed := range seeds {
			if err := refsStore.InsertArtFetch(ctx, seed.hash, seed.sha, "poster"); err != nil {
				t.Fatalf("InsertArtFetch %s: %v", seed.hash, err)
			}
		}
		refs, err := refsStore.ListArtFetchRefs(ctx)
		if err != nil {
			t.Fatalf("ListArtFetchRefs: %v", err)
		}
		want := []string{artHash64('0'), artHash64('9')} // DISTINCT + sha-ordered
		if len(refs) != len(want) {
			t.Fatalf("ListArtFetchRefs = %d refs (%v), want %d", len(refs), refs, len(want))
		}
		for i := range want {
			if refs[i] != want[i] {
				t.Fatalf("ListArtFetchRefs[%d] = %q, want %q (distinct, ordered)", i, refs[i], want[i])
			}
		}
		if err := refsStore.DeleteArtFetch(ctx, artHash64('h')); err != nil {
			t.Fatalf("DeleteArtFetch: %v", err)
		}
		if err := refsStore.DeleteArtFetch(ctx, artHash64('j')); err != nil {
			t.Fatalf("DeleteArtFetch: %v", err)
		}
		refs, err = refsStore.ListArtFetchRefs(ctx)
		if err != nil {
			t.Fatalf("ListArtFetchRefs after delete: %v", err)
		}
		if len(refs) != 1 || refs[0] != artHash64('0') {
			t.Fatalf("refs after delete = %v, want only %q", refs, artHash64('0'))
		}
	})
}

// TestArtListMethods covers the listing half of the artwork method set
// (artwork): both tables enumerate as parallel slices in deterministic order,
// an empty table yields empty (never nil-error), and a deleted row leaves the
// listing at once.
func TestArtListMethods(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	t.Run("empty_tables", func(t *testing.T) {
		hashes, shas, kinds, err := s.ListArtFetches(ctx)
		if err != nil || len(hashes) != 0 || len(shas) != 0 || len(kinds) != 0 {
			t.Fatalf("ListArtFetches empty = %v, %v, %v, %v; want empty slices, nil error", hashes, shas, kinds, err)
		}
		ids, kinds, selections, err := s.ListArtOverrides(ctx)
		if err != nil || len(ids) != 0 || len(kinds) != 0 || len(selections) != 0 {
			t.Fatalf("ListArtOverrides empty = %v, %v, %v, %v; want empty slices, nil error", ids, kinds, selections, err)
		}
	})

	t.Run("parallel_rows_deterministic", func(t *testing.T) {
		rows := []struct {
			hash, sha, kind string
		}{
			{"h_" + artHash64('3'), artHash64('c'), "poster"},
			{"h_" + artHash64('1'), artHash64('a'), "poster"},
			{"h_" + artHash64('2'), artHash64('b'), "backdrop"},
		}
		for _, r := range rows {
			if err := s.InsertArtFetch(ctx, r.hash, r.sha, r.kind); err != nil {
				t.Fatalf("InsertArtFetch %s: %v", r.hash, err)
			}
		}
		hashes, shas, kinds, err := s.ListArtFetches(ctx)
		if err != nil {
			t.Fatalf("ListArtFetches: %v", err)
		}
		if len(hashes) != 3 {
			t.Fatalf("rows = %d, want 3", len(hashes))
		}
		// url_hash-ascending: the h_1 row first, slices aligned.
		if hashes[0] != "h_"+artHash64('1') || shas[0] != artHash64('a') || kinds[0] != "poster" {
			t.Fatalf("row 0 = %s/%s/%s, want the h_1 row", hashes[0], shas[0], kinds[0])
		}
		if hashes[1] != "h_"+artHash64('2') || kinds[1] != "backdrop" {
			t.Fatalf("row 1 = %s/%s, want the h_2 backdrop row", hashes[1], kinds[1])
		}

		if _, err := s.UpsertArtOverride(ctx, "ser_2", "series", "art_"+artHash64('9')); err != nil {
			t.Fatalf("UpsertArtOverride: %v", err)
		}
		if _, err := s.UpsertArtOverride(ctx, "itm_1", "item", "src:shikimori"); err != nil {
			t.Fatalf("UpsertArtOverride: %v", err)
		}
		ids, kinds, selections, err := s.ListArtOverrides(ctx)
		if err != nil {
			t.Fatalf("ListArtOverrides: %v", err)
		}
		if len(ids) != 2 || ids[0] != "itm_1" || kinds[0] != "item" || selections[0] != "src:shikimori" {
			t.Fatalf("overrides = %v/%v/%v, want itm_1 row first (id-ascending)", ids, kinds, selections)
		}

		// A delete leaves the listing at once.
		if err := s.DeleteArtFetch(ctx, "h_"+artHash64('2')); err != nil {
			t.Fatalf("DeleteArtFetch: %v", err)
		}
		hashes, _, _, err = s.ListArtFetches(ctx)
		if err != nil || len(hashes) != 2 {
			t.Fatalf("rows after delete = %d, %v; want 2", len(hashes), err)
		}
	})
}
